using Arconist.Core;
using Arconist.Bridge;
using System.Text.Json;
class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
class Backend:IPausableBgmBackend
{
 public readonly List<string> Calls=new();public bool Playing,Paused;public double Position;public bool FailSeek;
 public void Load(string r){Calls.Add("load");Playing=Paused=false;Position=0;}
 public void PlayFromStart(){Calls.Add("play");Playing=true;}
 public void StopAndUnload(){Calls.Add("stop");Playing=Paused=false;}
 public void PausePlayback(){Calls.Add("pause");Paused=Playing;}
 public void SeekMilliseconds(int p){Calls.Add("seek:"+p);if(FailSeek)throw new InvalidOperationException("injected seek failure");Position=p/1000.0;}
 public void UnpausePlayback(){Calls.Add("unpause");Paused=false;}
 public BgmStatus Inspect()=>new(Playing,Position,32,"R008 fake, no output",paused:Paused,seekReadbackSeconds:Position);
}
class Program
{
 static int Main(string[] args)
 {
  string root=args.Length>0?args[0]:".",output=args.Length>1?args[1]:"arctap-bridge-evidence";Directory.CreateDirectory(output);int passed=0,failed=0;var outcomes=new List<object>();
  void Check(bool ok,string why){if(!ok)throw new Exception(why);}
  void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
  string Load(string n)=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",n));
  (Clock,GameplaySession) New(){var c=new Clock();var s=new GameplaySession(c);s.Start(Load("native_arc_tap.aff"));c.Milliseconds=3002;s.Frame();return(c,s);}
  SkyContact At(GameplaySession s)=>new(s.Core!.ArcTaps[0].InputTarget);
  Test("two fresh mouse DOWN pairs publish exactly one child event",()=>{var(c,s)=New();c.Milliseconds=4502;s.Frame();var events=new List<JudgmentEvent>();s.JudgmentsProduced+=e=>events.AddRange(e);s.Pointer(100,0,At(s),true);int first=s.Core!.Contacts.Single().Id;s.Pointer(100,0,null,false);s.Pointer(101,0,At(s),true);Check(s.Core!.Contacts.Single().Id!=first&&s.Core!.Classifications.Single().Outcome=="guard_consumed"&&s.Feedback=="SHINING PURE"&&events.Count==1&&events[0].Note==s.Core!.ArcTaps[0].Id&&events[0].CheckpointTime==null,"duplicate attributed to child guard");s.Pointer(101,0,null,false);Check(s.HeldCount==0&&s.Core!.ContactCount==0,"cleanup");});
  Test("held pointer and MOVE crossing due do not judge child",()=>{var(c,s)=New();c.Milliseconds=4002;s.Frame();s.Pointer(100,0,At(s),true);c.Milliseconds=4502;s.MovePointer(100,0,At(s));s.Frame();Check(s.Core!.Pure==0&&!s.Core!.ArcTaps[0].Consumed,"only initial DOWN");s.Pointer(100,0,null,false);s.Pointer(100,0,At(s),true);Check(s.Core!.Pure==1,"fresh DOWN after lift");});
  Test("echo duplicate physical DOWN and keyboard remain separate",()=>{var(c,s)=New();c.Milliseconds=4502;s.Frame();Check(!s.Pointer(100,0,At(s),true,true),"echo");s.Key('J',true);Check(s.Core!.Pure==0,"no sky keyboard");s.Pointer(100,0,At(s),true);Check(!s.Pointer(100,0,At(s),true)&&s.Core!.Pure==1,"held duplicate guard");s.ReleaseAll();Check(s.HeldCount==0,"release all");});
  Test("invalid retained position cannot create a child judgment",()=>{var(c,s)=New();c.Milliseconds=4502;s.Frame();s.Pointer(100,0,new SkyContact(new SkyPoint(float.NaN,300,0)),true);Check(s.Core!.Pure==0&&!s.Core!.ArcTaps[0].Consumed,"invalid spatial");s.MovePointer(100,0,At(s));s.Frame();Check(s.Core!.Pure==0,"MOVE after invalid DOWN not a tap");});
  Test("pause60seconds modal blocks DOWN and dismissal restores delivery",()=>{var(c,s)=New();c.Milliseconds=4402;s.Frame();s.Pause();c.Milliseconds=64402;s.Frame();Check(!s.Pointer(100,0,At(s),true)&&s.Core!.Timeline.EffectiveTime==1400&&s.Core!.ContactCount==0,"paused gate");s.Resume();Check(!s.PauseModalActive&&!s.Core!.ArcTaps[0].Consumed,"dismissed without award");c.Milliseconds=64502;s.Frame();s.Pointer(100,0,At(s),true);Check(s.Core!.Pure==1,"fresh click delivered");});
  Test("retained pre-pause contact UP during modal is genuine cleanup",()=>{var(c,s)=New();c.Milliseconds=4002;s.Frame();s.Pointer(100,0,At(s),true);c.Milliseconds=4402;s.Pause();Check(s.Pointer(100,0,null,false)&&s.Core!.ContactCount==0,"UP");c.Milliseconds=64402;s.Resume();c.Milliseconds=64502;s.Frame();Check(s.Core!.Pure==0,"no resurrection");s.Pointer(100,0,At(s),true);Check(s.Core!.Pure==1&&s.Core!.ArcTaps[0].Contact==1,"new ID");});
  Test("focus loss cancels contacts and never auto resumes",()=>{var(c,s)=New();c.Milliseconds=4002;s.Frame();s.Pointer(100,0,At(s),true);s.FocusLost();c.Milliseconds=64002;s.Frame();s.FocusReturned();Check(s.PauseModalActive&&s.Core!.Paused&&s.HeldCount==0&&!s.Core!.ArcTaps[0].Consumed,"focus policy");s.Resume();c.Milliseconds=64502;s.Frame();s.Pointer(100,0,At(s),true);Check(s.Core!.Pure==1,"fresh input restored");});
  Test("completion home replay replace child and contacts",()=>{var(c,s)=New();c.Milliseconds=4502;s.Frame();s.Pointer(100,0,At(s),true);var old=s.Core!.ArcTaps[0];c.Milliseconds=5503;s.Frame();Check(s.Core!.Result!.Score==10000001&&s.HeldCount==0,"completion cleanup");s.Home();s.Start(Load("native_arc_tap.aff"));Check(!ReferenceEquals(old,s.Core!.ArcTaps[0])&&!s.Core!.ArcTaps[0].Consumed&&s.Core!.Pure==0&&s.Core!.ContactCount==0,"fresh child");});
  Test("mixed chart event order score and replay",()=>{var c=new Clock();var s=new GameplaySession(c);s.Start(Load("arctap_practice.aff"));var events=new List<JudgmentEvent>();s.JudgmentsProduced+=e=>events.AddRange(e);c.Milliseconds=3002;s.Frame();for(int e=1;e<=10621;e++){c.Milliseconds=e+3002;foreach(var t in s.Core!.Chart.Taps.Where(t=>t.Time==e)){s.Contact(200+t.Ordinal,t.Lane,true);s.Contact(200+t.Ordinal,t.Lane,false);}if(e==6000){s.Pointer(100,0,At(s),true);s.Pointer(100,0,null,false);}s.Frame();}Check(s.Core!.Result!.Score==10000005&&events.Count==5&&events.Select(e=>e.Note).Distinct().Count()==5&&events[2].Note==s.Core!.ArcTaps[0].Id&&s.HeldCount==0,"mixed event identity");});
  Test("audio strict startup offset and seek preserve child clock",()=>{var c=new Clock();var b=new Backend();var s=new GameplaySession(c,b);s.Start(Load("native_arc_tap.aff"),120,"R008-audio-test","res://fake.bytes");c.Milliseconds=2880;s.Frame();Check(!s.Core!.Timeline.MusicStarted&&!b.Calls.Contains("play"),"strict equality");c.Milliseconds=2881;s.Frame();Check(s.Core!.Timeline.EffectiveTime==-120&&b.Calls.Count(x=>x=="play")==1,"anchor");c.Milliseconds=4401;s.Frame();Check(s.Core!.Timeline.EffectiveTime==1400,"offset clock");s.Pause();c.Milliseconds=64401;s.Frame();s.Resume();Check(b.Calls.TakeLast(2).SequenceEqual(new[]{"seek:1520","unpause"})&&!s.Core!.ArcTaps[0].Consumed&&s.Core!.Timeline.EffectiveTime==1400,"ordered offset resume");c.Milliseconds=64501;s.Frame();s.Pointer(100,0,At(s),true);Check(s.Core!.Pure==1&&b.Calls.Count(x=>x=="play")==1,"audio cannot alter judgment");s.Home();Check(!b.Playing,"audio cleanup");});
  Test("failed audio seek preserves paused unconsumed child for retry",()=>{var c=new Clock();var b=new Backend();var s=new GameplaySession(c,b);s.Start(Load("native_arc_tap.aff"),0,"R008-failure","res://fake.bytes");c.Milliseconds=3002;s.Frame();c.Milliseconds=4402;s.Frame();s.Pause();c.Milliseconds=64402;b.FailSeek=true;Check(!s.Resume()&&s.PauseModalActive&&s.Core!.Paused&&!s.Core!.ArcTaps[0].Consumed&&s.Core!.Pure==0,"safe error");b.FailSeek=false;Check(s.Resume(),"retry");c.Milliseconds=64502;s.Frame();s.Pointer(100,0,At(s),true);Check(s.Core!.Pure==1,"recovered input");});
  Test("selecting old charts after child result has fresh state",()=>{var(c,s)=New();c.Milliseconds=4502;s.Frame();s.Pointer(100,0,At(s),true);foreach(string name in new[]{"sky_practice.aff","mixed_practice.aff","audible_practice.aff"}){s.Start(Load(name));Check(s.Core!.ArcTaps.Count==0&&s.Core!.Pure==0&&s.HeldCount==0,"switch "+name);}});
  File.WriteAllText(Path.Combine(output,"arctap-bridge-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R008 bridge: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");return failed==0?0:1;
 }
}
